/**
 * UTC-offset transitions bundled with the app.
 *
 * `data/tzdata.json` is generated by `scripts/build-tzdata.mjs` from ICU and
 * covers 2018-01-01 → 2045-01-01 for every IANA zone `Intl` knows about.
 *
 * We ship it because the host can be wrong. Windows (and therefore Chromium on
 * Windows) still carries the pre-2018 Morocco rule: `Intl` there reports
 * Africa/Casablanca as UTC+0 in October 2026, while IANA — and Morocco since
 * 2018 — says UTC+1. Treating the OS as the single source of truth would make
 * every displayed minute one hour off for the app's main audience.
 *
 * The lookup is a binary search over a flat array, so formatting a month of
 * prayer times costs microseconds.
 */

import raw from './data/tzdata.json';

interface TzDataFile {
  version: number;
  source: string;
  start: number;
  end: number;
  /** Flat `[offset0, transition1Min, offset1, transition2Min, offset2, …]`. */
  series: number[][];
  zones: Record<string, number>;
}

const data = raw as TzDataFile;

/**
 * Versioned override for Morocco (Africa/Casablanca).
 *
 * Décret n° 2-26-530 du 25 juin 2026 (BO) : abrogation du dispositif de 2018 et
 * retour à GMT à partir du 20 septembre 2026 à 02 h 00 UTC. Les données IANA/tzdb
 * embarquées (tz 2026b) modélisent encore l'ancienne règle (suspension pendant
 * le Ramadan, puis retour à UTC+1), donc elles renvoient UTC+1 en octobre 2026.
 *
 * On conserve toutes les transitions historiques jusqu'au 20/09/2026 02:00 UTC,
 * puis on fixe définitivement UTC+0 à partir de ce point, sans inventer de
 * transition future. Ce correctif est documenté et testable ; il sera retiré
 * lorsqu'une version tzdb inclura le décret.
 */
const MOROCCO_OVERRIDE_CUTOFF_MIN = 4585080; // 2026-09-20T02:00:00Z, minutes depuis TZDATA_START
const MOROCCO_OVERRIDE_OFFSET = 0;

function applyMoroccoOverride(): void {
  const zoneIndex = data.zones['Africa/Casablanca'];
  if (zoneIndex === undefined) return;
  const original = data.series[zoneIndex];
  if (!original || original.length === 0) return;

  const patched: number[] = [original[0]!];
  for (let i = 1; i < original.length; i += 2) {
    const transition = original[i]!;
    if (transition >= MOROCCO_OVERRIDE_CUTOFF_MIN) break;
    patched.push(transition, original[i + 1]!);
  }
  const currentOffset = patched[patched.length - 1]!;
  if (currentOffset !== MOROCCO_OVERRIDE_OFFSET) {
    patched.push(MOROCCO_OVERRIDE_CUTOFF_MIN, MOROCCO_OVERRIDE_OFFSET);
  }

  const newIndex = data.series.length;
  data.series.push(patched);
  data.zones['Africa/Casablanca'] = newIndex;
}

applyMoroccoOverride();

/** e.g. "ICU 78.3 (tz 2026b) via Node 24.19.0 + patch Maroc décret 2-26-530" */
export const TZDATA_SOURCE = `${data.source} + patch Maroc décret 2-26-530 (2026-09-20)`;
export const TZDATA_START = data.start;
export const TZDATA_END = data.end;

export function hasBundledZone(timeZone: string): boolean {
  return Object.prototype.hasOwnProperty.call(data.zones, timeZone);
}

export function bundledZoneCount(): number {
  return Object.keys(data.zones).length;
}

/**
 * Offset in minutes east of UTC, or `null` when the zone is unknown to the table
 * or the instant falls outside the generated range.
 */
export function bundledOffsetMinutes(timeZone: string, utcMs: number): number | null {
  if (!Number.isFinite(utcMs) || utcMs < data.start || utcMs >= data.end) return null;
  const zoneIndex = data.zones[timeZone];
  if (zoneIndex === undefined) return null;
  const series = data.series[zoneIndex];
  if (!series || series.length === 0) return null;

  const minutes = (utcMs - data.start) / 60_000;
  const transitionCount = (series.length - 1) / 2;
  let lo = 0;
  let hi = transitionCount;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (series[1 + mid * 2]! <= minutes) lo = mid + 1;
    else hi = mid;
  }
  if (lo === 0) return series[0]!;
  return series[1 + (lo - 1) * 2 + 1]!;
}

/** Every zone the table can answer for, sorted. Used by the picker. */
export function bundledZones(): string[] {
  return Object.keys(data.zones).sort();
}
